p='live/vuon3d.html'; s=open(p).read()
def rep(a,b,cnt=1):
    global s
    n=s.count(a); assert n==cnt,(a[:90],n); s=s.replace(a,b)
# --- FT definitions
rep("  duahau: { name: 'Dưa hấu', story: 'Mai An Tiêm', lv: 14, soon: 1, hint: 'Để một ô cát trống mé sông qua đêm, có bữa chim thả hạt lạ xuống.', cond: 'Mé sông đã mở, chừa một ô cát trống qua đêm' },",
"  duahau: { name: 'Dưa hấu', story: 'Mai An Tiêm', lv: 14, at: [-1.4, 6.2], max: 3, dur: [0, 8 * 3600, 12 * 3600], hint: 'Chừa một ô đất trống ngoài mé sông qua đêm, có bữa chim thả hạt lạ xuống.', cond: 'Chừa một ô đất trống ở mé sông qua đêm',\n    parts: ['Hồi xưa có chàng Mai An Tiêm được vua thương nhận làm con nuôi. Chàng hay nói: của cải mình có là do mình làm ra. Vua giận, đày cả nhà chàng ra hòn đảo hoang ngoài biển.', 'Trên đảo toàn cát với đá. Một bữa có bầy chim bay ngang, thả xuống mấy hột đen nhánh. An Tiêm nói chim ăn được thì người ăn được, đem hột đi gieo. Dây bò kín cát, ra trái vỏ xanh, ruột đỏ, ngọt lịm.', 'An Tiêm khắc tên lên trái dưa, thả xuống biển cho sóng đưa vô đất liền. Người ta vớt được, đổi gạo cho chàng. Vua nghe chuyện, biết mình sai, rước cả nhà về. Trái dưa con chăm, Ngoại cũng khắc tên con lên đó.'] },")
rep("  khevang: { name: 'Khế vàng', story: 'Ăn khế trả vàng', lv: 16, soon: 1, hint: 'Cây khế cho trái hoài, con chừa vài trái cho chim. Có bữa chim lạ bay tới đó.', cond: 'Cây khế cho 5 vụ, vụ cuối chừa lại vài trái' },",
"  khevang: { name: 'Khế vàng', story: 'Ăn khế trả vàng', lv: 16, at: [-9.6, 6.9], max: 3, dur: [0, 8 * 3600, 12 * 3600], hint: 'Cây khế cho trái hoài, có bữa chim lạ bay tới ăn khế đó con.', cond: 'Hái cây khế đủ 5 vụ',\n    parts: ['Hồi xưa có hai anh em. Cha mẹ mất, người anh tham lấy hết ruộng vườn, chỉ chừa cho em một cây khế góc vườn. Người em hiền, ngày ngày chăm cây.', 'Cây khế ra trái sai oằn. Có con chim lớn bay tới ăn khế, người em than một tiếng, chim nói: ăn một quả, trả cục vàng, may túi ba gang, mang đi mà đựng. Chim chở người em ra đảo xa, người em lấy vàng vừa đủ túi rồi về, từ đó bớt nghèo.', 'Người anh hay chuyện, đòi đổi hết gia tài lấy cây khế. Chim lại tới, người anh may túi mười hai gang, nhét vàng đầy túi, chim chở không nổi, rớt xuống biển. Ngoại kể để con nhớ: đủ là đủ, tham thì thâm. Mỗi tuần chim còn ghé cây khế mình, để lại một cục vàng nhỏ.'] },")
rep("  sodua: { name: 'Sọ Dừa', story: 'Sọ Dừa', lv: 18, soon: 1, hint: 'Cây dừa cho ba vụ rồi, có trái dừa lạ lắm, nghe đâu biết nói.', cond: 'Cây dừa cho 3 vụ' } };",
"  sodua: { name: 'Sọ Dừa', story: 'Sọ Dừa', lv: 18, at: [-7.3, 8.5], max: 3, dur: [0, 8 * 3600, 12 * 3600], hint: 'Cây dừa mé sông cho ba vụ rồi, có trái dừa lạ lắm, nghe đâu biết nói.', cond: 'Hái cây dừa đủ 3 vụ',\n    parts: ['Hồi xưa có bà mẹ nghèo đi ở cho nhà phú ông, sinh ra đứa con tròn lông lốc như trái dừa, không tay không chân. Bà buồn mà vẫn thương, đặt tên là Sọ Dừa.', 'Sọ Dừa xin đi chăn bò cho phú ông. Bò con nào cũng no căng. Cô út nhà phú ông đem cơm ra đồng, lén thấy một chàng trai thổi sáo hay lắm, lại gần thì chỉ còn trái dừa lăn lóc. Cô biết Sọ Dừa không phải người thường.', 'Sọ Dừa cưới cô út, cởi lớp vỏ dừa thành chàng trai khôi ngô, học giỏi đỗ trạng. Ngoại kể để con nhớ đừng coi người ta bằng cái vỏ bề ngoài. Trái dừa của mình giờ cũng biết nói, rảnh là lăn ra tưới giùm con một liếp.'] } };")
