rep("  if ((ST.lv || 1) >= FT.traucau.lv && (ST.guestN || 0) + (ST.visitOut || 0) >= 5 && !ST.ft.traucau){ ST.ft.traucau = { st: 0, told: 0, t: Date.now() }; save(); }",
"  if ((ST.lv || 1) >= FT.traucau.lv && (ST.guestN || 0) + (ST.visitOut || 0) >= 5 && !ST.ft.traucau){ ST.ft.traucau = { st: 0, told: 0, t: Date.now() }; save(); }\n  if ((ST.lv || 1) >= FT.duahau.lv && !ST.ft.duahau){ const dk = dayKey(), h = HOUR, night = h >= 20 || h < 4, free = PLOTS.some(P => P.zone === 'song' && ST.open.includes(P.id) && !ST.plots[P.id].crop); if (free && night && !ST.dhN) ST.dhN = dk; else if (!free) ST.dhN = ''; if (ST.dhN && ST.dhN !== dk && h >= 5 && free){ ST.ft.duahau = { st: 0, told: 0, t: Date.now() }; save(); } }   /* chừa ô đất mé sông qua một đêm, sáng ra chim thả hạt */\n  if ((ST.lv || 1) >= FT.khevang.lv && (ST.kheHv || 0) >= 5 && !ST.ft.khevang){ ST.ft.khevang = { st: 0, told: 0, t: Date.now() }; save(); }\n  if ((ST.lv || 1) >= FT.sodua.lv && (ST.duaHv || 0) >= 3 && !ST.ft.sodua){ ST.ft.sodua = { st: 0, told: 0, t: Date.now() }; save(); }\n  sdHelp();")
rep("if (k0 === 'khoqua') ST.kqHv = (ST.kqHv || 0) + 1;", "if (k0 === 'khoqua') ST.kqHv = (ST.kqHv || 0) + 1; if (k0 === 'khe') ST.kheHv = (ST.kheHv || 0) + 1; if (k0 === 'dua') ST.duaHv = (ST.duaHv || 0) + 1; if (c.tree) ST.treeHv = (ST.treeHv || 0) + 1;")
# --- rewards on tap
rep("if (F.st >= FT[k].max) openBook('cotich'); else bark(",
"if (k === 'duahau' && F.st >= 3 && F.told >= 3){ if (F.fd && Date.now() - F.fd < 2 * 864e5) return toast('Trái dưa mới hái, hai bữa nữa có trái khác.'); F.fd = Date.now(); ST.inv.duahau = (ST.inv.duahau || 0) + 1; const A = ftPos(k); flyTo(ICON.duahau, A[0], .6, A[1]); floatAt(A[0], 1.2, A[1], `+1 trái dưa khắc tên ${ST.player ? ST.player.name : ''}`, '#9fd36a'); sfx('pop'); save(); hud(); return; }\n  if (k === 'khevang' && F.st >= 3 && F.told >= 3){ if (F.wk === wkKey()) return toast('Tuần này chim đã gửi vàng rồi, tuần sau ghé lại.'); F.wk = wkKey(); ST.vang = (ST.vang || 0) + 1; const A = ftPos(k); for (let i = 0; i < 16; i++) puff('spark', A[0], 1.6, A[1], 1, '#FFD45A', 1.2); floatAt(A[0], 2.2, A[1], '+1 cục vàng · đổi đồ kiểng, sửa nhà', '#FFD45A'); sfx('up'); save(); hud(); sayOnce('vang1', 'Cục vàng này để dành mua đồ kiểng, sửa nhà nghe con. Mỗi cục trừ được ba trăm xu.', 'vui'); return; }\n  if (k === 'sodua' && F.st >= 3 && F.told >= 3){ const A = ftPos(k); floatAt(A[0], 1.2, A[1], 'Sọ Dừa lo tưới giùm liếp khô đó', '#F0FFC0'); sfx('pop'); return; }\n  if (F.st >= FT[k].max) openBook('cotich'); else bark(")
# helper: Sọ Dừa waters one dry bed every ~20 minutes
rep("function ftCheck(){", "function sdHelp(){ const F = ST.ft.sodua; if (!F || F.st < 3 || F.told < 3 || VISIT) return; const now = Date.now(); if (now - (ST.sdW || 0) < 20 * 60000) return; const P = PLOTS.find(P => { const p = ST.plots[P.id]; return p && p.crop && !p.dead && !P.trellis && p.moist <= 0; }); if (!P) return; ST.sdW = now; try { act.water(P.id); } catch (e) { return; } const v = PV[P.id]; if (v) floatAt(v.cx, .9, v.cz, 'Sọ Dừa tưới giùm', '#F0FFC0'); }   /* Sọ Dừa lớn rồi: chừng hai chục phút lăn ra tưới giùm một liếp khô */\nfunction ftCheck(){")
